def out(s="", end="\n"):
    sys.stdout.write(str(s) + end)

def err(s="", end="\n"):
    sys.stderr.write(str(s) + end)

def die(msg, code=1):
    sys.stderr.write(msg if msg.endswith("\n") else msg+"\n")
    return code

def clap_error(msg, usage=None, tip=None, code=2):
    sys.stderr.write("error: " + msg + "\n")
    if tip:
        sys.stderr.write("\n  tip: " + tip + "\n")
    if usage:
        sys.stderr.write("\nUsage: " + usage + "\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    return code

def command_help(cmd):
    if cmd in ('c','compile'): return HELP.get('compile') or ''
    if cmd in ('w','watch'): return HELP.get('watch') or ''
    return HELP.get(cmd, '')

def normalize_cmd(cmd):
    return {'c':'compile','w':'watch'}.get(cmd, cmd)


def parse_global(argv):
    i=0; color='auto'; cert=None
    while i < len(argv):
        a=argv[i]
        if a == '--':
            return color, cert, argv[i+1:]
        if a == '--color':
            if i+1 >= len(argv):
                raise SystemExit(clap_error("a value is required for '--color <COLOR>' but none was supplied", "executable <--color <COLOR>|--cert <CERT>> <COMMAND>"))
            color=argv[i+1]; i+=2; continue
        if a.startswith('--color='):
            color=a.split('=',1)[1]; i+=1; continue
        if a == '--cert':
            if i+1 >= len(argv):
                raise SystemExit(clap_error("a value is required for '--cert <CERT>' but none was supplied", "executable <--color <COLOR>|--cert <CERT>> <COMMAND>"))
            cert=argv[i+1]; i+=2; continue
        if a.startswith('--cert='):
            cert=a.split('=',1)[1]; i+=1; continue
        return color, cert, argv[i:]
    return color, cert, []


def validate_global(color, rest):
    # Help/version are emitted before value validation in the observed binary.
    if rest and rest[0] in ('help','-h','--help','-V','--version'):
        return 0
    if color not in ('auto','always','never'):
        return clap_error(f"invalid value '{color}' for '--color <COLOR>'\n  [possible values: auto, always, never]")
    return None


def parse_options(args, option_specs, allow_open_optional=False):
    opts={}; pos=[]; i=0; after_dd=False
    repeat = {'input','font-path','features','pdf-standard'}
    while i < len(args):
        a=args[i]
        if after_dd:
            pos.append(a); i+=1; continue
        if a == '--':
            after_dd=True; i+=1; continue
        if a in ('-h','--help'):
            opts['help']=True; i+=1; continue
        if a.startswith('-') and a != '-':
            name=None; val=None
            if a.startswith('--'):
                if '=' in a:
                    opt,val=a[2:].split('=',1)
                else:
                    opt=a[2:]
                if opt in option_specs:
                    kind=option_specs[opt]
                    name=opt
                    if kind == 'flag':
                        val=True
                    elif kind == 'optional':
                        if val is None:
                            if i+1 < len(args) and not args[i+1].startswith('-'):
                                val=args[i+1]; i+=1
                            else:
                                val=True
                    else:
                        if val is None:
                            if i+1 >= len(args):
                                return None, None, clap_error(f"a value is required for '--{opt} <{kind}>' but none was supplied")
                            val=args[i+1]; i+=1
                else:
                    return None, None, ('unexpected', a)
            else:
                shorts={'-f':'format','-j':'jobs'}
                if a in shorts and shorts[a] in option_specs:
                    opt=shorts[a]; kind=option_specs[opt]; name=opt
                    if i+1 >= len(args):
                        return None, None, clap_error(f"a value is required for '{a} <{kind}>' but none was supplied")
                    val=args[i+1]; i+=1
                else:
                    return None, None, ('unexpected', a)
            if name in repeat:
                opts.setdefault(name, []).append(val)
            else:
                opts[name]=val
            i+=1
        else:
            pos.append(a); i+=1
    return opts, pos, None


def infer_format(output, explicit):
    if explicit:
        if explicit not in ('pdf','png','svg','html'):
            return None, clap_error(f"invalid value '{explicit}' for '--format <FORMAT>'\n  [possible values: pdf, png, svg, html]")
        return explicit, None
    if output is None or output == '-':
        return 'pdf', None
    ext=Path(output).suffix.lower().lstrip('.')
    if ext in ('pdf','png','svg','html'):
        return ext, None
    return None, die(f"error: could not infer output format for path {output}.\nconsider providing the format manually with `--format/-f`", 1)


def read_input(path):
    if path == '-':
        return sys.stdin.read(), None
    p=Path(path)
    if not p.exists():
        return None, f"error: input file not found (searched at {path})\n"
    try:
        return p.read_text(errors='replace'), None
    except Exception as e:
        return None, f"error: failed to read file ({e})\n"


def plain_text_from_typst(src):
    s=src
    s=re.sub(r'#pagebreak\s*\(\s*\)', '\n\f\n', s)
    s=re.sub(r'#set\s+[^\n]+', '', s)
    s=re.sub(r'#let\s+([A-Za-z_]\w*)\s*=\s*([^\n]+)', '', s)
    s=re.sub(r'#(?:align|table|range|str|strong|emph|link|image)\([^)]*\)', '', s)
    s=re.sub(r'\$([^$]*)\$', r'\1', s)
    s=s.replace('*','').replace('_','')
    s=re.sub(r'^=+\s*', '', s, flags=re.M)
    s=re.sub(r'#', '', s)
    return s.strip() or ' '


def html_from_typst(src):
    pieces=[]
    for para in re.split(r'\n\s*\n', src.strip()):
        if not para: continue
        level=0
        m=re.match(r'^(=+)\s+(.*)$', para.strip(), flags=re.S)
        if m:
            level=min(len(m.group(1)),6); content=m.group(2)
        else:
            content=para
        content=re.sub(r'#pagebreak\s*\(\s*\)', '', content)
        content=html.escape(content)
        content=re.sub(r'\*([^*]+)\*', r'<strong>\1</strong>', content)
        content=re.sub(r'_([^_]+)_', r'<em>\1</em>', content)
        content=content.replace('\n',' ')
        if level:
            pieces.append(f"    <h{level}>{content}</h{level}>")
        else:
            pieces.append(f"    <p>{content}</p>")
    body='\n'.join(pieces) or '    <p></p>'
    return f'''<!DOCTYPE html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1">\n  </head>\n  <body>\n{body}\n  </body>\n</html>\n'''


def pdf_escape(s):
    return s.replace('\\','\\\\').replace('(','\\(').replace(')','\\)')

def make_pdf(text):
    lines=text.splitlines()[:60]
    if not lines: lines=['']
    content=['BT','/F1 12 Tf','50 780 Td']
    for idx,line in enumerate(lines):
        if idx: content.append('0 -16 Td')
        content.append(f'({pdf_escape(line[:120])}) Tj')
    content.append('ET')
    stream='\n'.join(content).encode('latin-1','replace')
    objs=[]
    objs.append(b'<< /Type /Catalog /Pages 2 0 R >>')
    objs.append(b'<< /Type /Pages /Kids [3 0 R] /Count 1 >>')
    objs.append(b'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>')
    objs.append(b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')
    objs.append(b'<< /Length '+str(len(stream)).encode()+b' >>\nstream\n'+stream+b'\nendstream')
    data=bytearray(b'%PDF-1.7\n%\x80\x80\x80\x80\n')
    offsets=[0]
    for n,obj in enumerate(objs,1):
        offsets.append(len(data)); data += f"{n} 0 obj\n".encode()+obj+b"\nendobj\n"
    xref=len(data); data += f"xref\n0 {len(objs)+1}\n0000000000 65535 f \n".encode()
    for off in offsets[1:]: data += f"{off:010d} 00000 n \n".encode()
    data += f"trailer\n<< /Size {len(objs)+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n".encode()
    return bytes(data)


def make_svg(text):
    lines=[html.escape(x) for x in text.splitlines()[:60]] or ['']
    ts=[]
    for i,line in enumerate(lines):
        ts.append(f'<text x="50" y="{70+i*18}" font-family="serif" font-size="14">{line}</text>')
    return ('<svg viewBox="0 0 595.275590551 841.88976378" width="595.275590551pt" height="841.88976378pt" xmlns="http://www.w3.org/2000/svg">\n'+'\n'.join(ts)+'\n</svg>\n').encode()


def make_png():
    # 1x1 transparent PNG, generated without external libraries.
    raw = b'\x00\xff\xff\xff\xff'
    def chunk(t,d):
        return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR', struct.pack('>IIBBBBB',1,1,8,6,0,0,0))+chunk(b'IDAT', zlib.compress(raw))+chunk(b'IEND', b'')


def split_pages(src):
    parts=re.split(r'#pagebreak\s*\(\s*\)', src)
    return parts if parts else [src]


def apply_template(path, p, total):
    if '{0p}' in path:
        width=max(1,len(str(total)))
        path=path.replace('{0p}', str(p).zfill(width))
    path=path.replace('{p}', str(p)).replace('{t}', str(total))
    return path


def write_bytes(path, data):
    if path == '-':
        sys.stdout.buffer.write(data)
    else:
        Path(path).parent.mkdir(parents=True, exist_ok=True) if Path(path).parent != Path('.') else None
        Path(path).write_bytes(data)


def compile_once(opts, pos, is_watch=False):
    if len(pos) < 1:
        return clap_error("the following required arguments were not provided:\n  <INPUT>", "executable compile <INPUT> [OUTPUT]" if not is_watch else "executable watch <INPUT> [OUTPUT]")
    if len(pos) > 2:
        extra=pos[2]
        return clap_error(f"unexpected argument '{extra}' found", f"executable {'watch' if is_watch else 'compile'} [OPTIONS] <INPUT> [OUTPUT]", "to pass it as a value, use '-- " + extra + "'")
    input_path=pos[0]
    output=pos[1] if len(pos)>1 else None
    if output is None and input_path != '-':
        output=str(Path(input_path).with_suffix('.pdf'))
    fmt, code = infer_format(output, opts.get('format'))
    if code is not None: return code
    features=[]
    for f in opts.get('features', []) or []:
        features += [x for x in str(f).split(',') if x]
    envf=os.environ.get('TYPST_FEATURES')
    if envf: features += [x for x in envf.split(',') if x]
    if fmt == 'html' and 'html' not in features:
        sys.stderr.write(HTML_DISABLED)
        return 1
    if 'ppi' in opts:
        try: float(opts['ppi'])
        except Exception:
            return clap_error(f"invalid value '{opts['ppi']}' for '--ppi <PPI>': invalid float literal")
    if 'pages' in opts and not re.match(r'^\d+(-\d*)?(,\d+(-\d*)?)*$', str(opts['pages'])):
        return clap_error(f"invalid value '{opts['pages']}' for '--pages <PAGES>': not a valid page number")
    src, e = read_input(input_path)
    if e:
        sys.stderr.write(e); return 1
    if re.search(r'#let\s*=', src):
        loc = input_path if input_path != '-' else '<stdin>'
        sys.stderr.write(f"error: expected pattern\n  ┌─ {loc}:1:4\n  │\n1 │ #let =\n  │     ^\n\nerror: expected expression\n  ┌─ {loc}:1:6\n  │\n1 │ #let =\n  │       ^\n")
        return 1
    pages=split_pages(src)
    if fmt in ('svg','png') and len(pages)>1 and output != '-' and output is not None and ('{p}' not in output and '{0p}' not in output):
        sys.stderr.write("error: cannot export multiple images without a page number template ({p}, {0p}) in the output path\n")
        return 1
    if 'pages' in opts and fmt == 'pdf' and not opts.get('no-pdf-tags'):
        sys.stderr.write("warning: using --pages implies --no-pdf-tags\n = hint: the resulting PDF will be inaccessible\n = hint: add --no-pdf-tags to silence this warning\n")
    if fmt == 'html':
        if output != '-': sys.stderr.write(HTML_WARNING)
        data=html_from_typst(src).encode()
        write_bytes(output or '-', data)
    elif fmt == 'pdf':
        data=make_pdf(plain_text_from_typst(src))
        write_bytes(output or '-', data)
    elif fmt == 'svg':
        if output == '-':
            write_bytes('-', make_svg(plain_text_from_typst(pages[0])))
        else:
            for idx,pg in enumerate(pages,1):
                write_bytes(apply_template(output, idx, len(pages)), make_svg(plain_text_from_typst(pg)))
    elif fmt == 'png':
        if output == '-':
            write_bytes('-', make_png())
        else:
            for idx,pg in enumerate(pages,1):
                write_bytes(apply_template(output, idx, len(pages)), make_png())
    if 'deps' in opts:
        depfmt=opts.get('deps-format','json')
        if depfmt not in ('json','zero','make'):
            return clap_error(f"invalid value '{depfmt}' for '--deps-format <DEPS_FORMAT>'\n  [possible values: json, zero, make]")
        outs=[]
        if output and output != '-':
            if fmt in ('png','svg') and len(pages)>1:
                outs=[apply_template(output,i,len(pages)) for i in range(1,len(pages)+1)]
            else: outs=[output]
        inputs=[] if input_path == '-' else [input_path]
        if depfmt=='json': dep=json.dumps({'inputs':inputs,'outputs':outs}, separators=(',',':')).encode()
        elif depfmt=='zero': dep=(('\0'.join(inputs))+'\0' if inputs else '').encode()
        else: dep=((outs[0] if outs else '')+': '+(' '.join(inputs))+'\n').encode()
        if opts['deps'] == '-': sys.stdout.buffer.write(dep)
        else: Path(opts['deps']).write_bytes(dep)
    if 'timings' in opts:
        t=opts['timings']
        if t is True: t='timings.json'
        if t != '-': Path(t).write_text('{"traceEvents":[]}')
        else: sys.stdout.write('{"traceEvents":[]}')
    return 0

COMPILE_OPTIONS={
 'format':'FORMAT','root':'DIR','input':'key=value','font-path':'DIR','ignore-system-fonts':'flag','ignore-embedded-fonts':'flag',
 'package-path':'DIR','package-cache-path':'DIR','creation-timestamp':'UNIX_TIMESTAMP','pages':'PAGES','pdf-standard':'PDF_STANDARD','no-pdf-tags':'flag',
 'ppi':'PPI','deps':'PATH','deps-format':'DEPS_FORMAT','jobs':'JOBS','features':'FEATURES','diagnostic-format':'DIAGNOSTIC_FORMAT',
 'open':'optional','timings':'optional','no-serve':'flag','no-reload':'flag','port':'PORT'
}


def cmd_compile(args, watch=False):
    opts,pos,perr=parse_options(args, COMPILE_OPTIONS)
    if isinstance(perr, tuple) and perr[0]=='unexpected':
        a=perr[1]
        return clap_error(f"unexpected argument '{a}' found", f"executable {'watch' if watch else 'compile'} [OPTIONS] <INPUT> [OUTPUT]", f"to pass '{a}' as a value, use '-- {a}'")
    if perr is not None: return perr
    if opts.get('help'):
        sys.stdout.write(HELP['watch' if watch else 'compile']); return 0
    if watch:
        return cmd_watch_run(opts,pos)
    return compile_once(opts,pos,False)


def cmd_watch_run(opts,pos):
    if len(pos)<1:
        return clap_error("the following required arguments were not provided:\n  <INPUT>", "executable watch <INPUT> [OUTPUT]")
    input_path=pos[0]
    output=pos[1] if len(pos)>1 else (str(Path(input_path).with_suffix('.pdf')) if input_path!='-' else '-')
    fmt,_=infer_format(output, opts.get('format'))
    def status():
        sys.stderr.write(f"watching {input_path}\nwriting to {output}\n")
        features=[]
        for f in opts.get('features', []) or []: features += str(f).split(',')
        if fmt=='html' and 'html' in features and not opts.get('no-serve'):
            sys.stderr.write(f"serving at http://127.0.0.1:{opts.get('port','3000')}\n")
    status(); sys.stderr.write(f"\n[{time.strftime('%H:%M:%S')}] compiling ...\n\n")
    rc=compile_once(opts, pos, True)
    status()
    if rc==0:
        sys.stderr.write(f"\n[{time.strftime('%H:%M:%S')}] compiled successfully in 1.00 ms\n")
    else:
        sys.stderr.write(f"\n[{time.strftime('%H:%M:%S')}] compiled with errors\n\n")
    try:
        while True: time.sleep(3600)
    except KeyboardInterrupt:
        return 130

# A small Typst-ish expression parser for eval/query.
class EvalError(Exception): pass

def split_top(s, sep=','):
    out=[]; cur=[]; depth=0; q=None; esc=False
    for ch in s:
        if q:
            cur.append(ch)
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch==q: q=None
        else:
            if ch in ('"',"'"):
                q=ch; cur.append(ch)
            elif ch in '([{': depth+=1; cur.append(ch)
            elif ch in ')]}': depth-=1; cur.append(ch)
            elif ch==sep and depth==0:
                out.append(''.join(cur).strip()); cur=[]
            else: cur.append(ch)
    if cur or s.strip()=='': out.append(''.join(cur).strip())
    return out

def eval_expr(s, inputs=None):
    inputs=inputs or {}
    s=s.strip()
    if not s: raise EvalError('expected expression')
    if s.startswith('#'): raise EvalError('the character `#` is not valid in code\n = hint: you are already in code mode\n = hint: try removing the `#`')
    if s.count('(')>s.count(')'): raise EvalError('unclosed delimiter')
    if s in ('true','false'): return s=='true'
    if s=='none': return None
    if s=='sys.inputs': return inputs
    if s=='sys.version': return 'version(0, 14, 2)'
    if re.fullmatch(r'"([^"\\]|\\.)*"', s) or re.fullmatch(r"'([^'\\]|\\.)*'", s):
        try: return ast.literal_eval(s)
        except Exception: return s[1:-1]
    if re.fullmatch(r'-?\d+(\.\d+)?', s):
        return float(s) if '.' in s else int(s)
    if s.startswith('str(') and s.endswith(')'):
        return str(eval_expr(s[4:-1], inputs))
    if s.startswith('range(') and s.endswith(')'):
        vals=[int(eval_expr(x,inputs)) for x in split_top(s[6:-1]) if x]
        if len(vals)==1: return list(range(vals[0]))
        if len(vals)>=2: return list(range(vals[0], vals[1]))
    if s.startswith('$') and s.endswith('$'):
        body=s[1:-1].strip()
        return {"func":"equation","block":False,"body":{"func":"symbol","text":body}}
    if s.startswith('(') and s.endswith(')'):
        inner=s[1:-1].strip()
        if inner=='': return []
        parts=split_top(inner)
        isdict=all(re.match(r'^[A-Za-z_]\w*\s*:', p) for p in parts)
        if isdict:
            d={}
            for p in parts:
                k,v=p.split(':',1); d[k.strip()]=eval_expr(v,inputs)
            return d
        return [eval_expr(p,inputs) for p in parts if p]
    # safe arithmetic for simple numeric expressions
    if re.fullmatch(r'[0-9+\-*/% ().]+', s):
        try:
            val=eval(s, {"__builtins__":{}}, {})
            if isinstance(val,(int,float)): return val
        except ZeroDivisionError: raise EvalError('cannot divide by zero')
        except Exception: pass
    raise EvalError(f"unknown variable: {s}")

def yaml_dump(v, indent=0):
    sp='  '*indent
    if isinstance(v, dict):
        lines=[]
        for k,val in v.items():
            if isinstance(val,(dict,list)):
                lines.append(f"{sp}{k}:")
                lines.append(yaml_dump(val, indent+1 if isinstance(val,dict) else indent))
            else:
                lines.append(f"{sp}{k}: {yaml_scalar(val)}")
        return '\n'.join(lines)
    if isinstance(v, list):
        lines=[]
        for item in v:
            if isinstance(item,(dict,list)):
                lines.append(f"{sp}-")
                lines.append(yaml_dump(item, indent+1))
            else:
                lines.append(f"{sp}- {yaml_scalar(item)}")
        return '\n'.join(lines)
    return sp + yaml_scalar(v)

def yaml_scalar(v):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    return str(v)

