def cmd_compile(args, watch=False):
    opts,pos,perr=parse_options(args, COMPILE_OPTIONS)
    if isinstance(perr, tuple) and perr[0]=='unexpected':
        a=perr[1]
        return clap_error(f"unexpected argument '{a}' found", f"executable {'watch' if watch else 'compile'} [OPTIONS] <INPUT> [OUTPUT]", f"to pass '{a}' as a value, use '-- {a}'")
    if perr is not None: return perr
    if opts.get('help'):
        sys.stdout.write(HELP['watch' if watch else 'compile']); return 0
    if watch:
        return cmd_watch_run(opts,pos)
    return compile_once(opts,pos,False)


def cmd_watch_run(opts,pos):
    if len(pos)<1:
        return clap_error("the following required arguments were not provided:\n  <INPUT>", "executable watch <INPUT> [OUTPUT]")
    input_path=pos[0]
    output=pos[1] if len(pos)>1 else (str(Path(input_path).with_suffix('.pdf')) if input_path!='-' else '-')
    fmt,_=infer_format(output, opts.get('format'))
    def status():
        sys.stderr.write(f"watching {input_path}\nwriting to {output}\n")
        features=[]
        for f in opts.get('features', []) or []: features += str(f).split(',')
        if fmt=='html' and 'html' in features and not opts.get('no-serve'):
            sys.stderr.write(f"serving at http://127.0.0.1:{opts.get('port','3000')}\n")
    status(); sys.stderr.write(f"\n[{time.strftime('%H:%M:%S')}] compiling ...\n\n")
    rc=compile_once(opts, pos, True)
    status()
    if rc==0:
        sys.stderr.write(f"\n[{time.strftime('%H:%M:%S')}] compiled successfully in 1.00 ms\n")
    else:
        sys.stderr.write(f"\n[{time.strftime('%H:%M:%S')}] compiled with errors\n\n")
    try:
        while True: time.sleep(3600)
    except KeyboardInterrupt:
        return 130

# A small Typst-ish expression parser for eval/query.
class EvalError(Exception): pass

def split_top(s, sep=','):
    out=[]; cur=[]; depth=0; q=None; esc=False
    for ch in s:
        if q:
            cur.append(ch)
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch==q: q=None
        else:
            if ch in ('"',"'"):
                q=ch; cur.append(ch)
            elif ch in '([{': depth+=1; cur.append(ch)
            elif ch in ')]}': depth-=1; cur.append(ch)
            elif ch==sep and depth==0:
                out.append(''.join(cur).strip()); cur=[]
            else: cur.append(ch)
    if cur or s.strip()=='': out.append(''.join(cur).strip())
    return out

def eval_expr(s, inputs=None):
    inputs=inputs or {}
    s=s.strip()
    if not s: raise EvalError('expected expression')
    if s.startswith('#'): raise EvalError('the character `#` is not valid in code\n = hint: you are already in code mode\n = hint: try removing the `#`')
    if s.count('(')>s.count(')'): raise EvalError('unclosed delimiter')
    if s in ('true','false'): return s=='true'
    if s=='none': return None
    if s=='sys.inputs': return inputs
    if s=='sys.version': return 'version(0, 14, 2)'
    if re.fullmatch(r'"([^"\\]|\\.)*"', s) or re.fullmatch(r"'([^'\\]|\\.)*'", s):
        try: return ast.literal_eval(s)
        except Exception: return s[1:-1]
    if re.fullmatch(r'-?\d+(\.\d+)?', s):
        return float(s) if '.' in s else int(s)
    if s.startswith('str(') and s.endswith(')'):
        return str(eval_expr(s[4:-1], inputs))
    if s.startswith('range(') and s.endswith(')'):
        vals=[int(eval_expr(x,inputs)) for x in split_top(s[6:-1]) if x]
        if len(vals)==1: return list(range(vals[0]))
        if len(vals)>=2: return list(range(vals[0], vals[1]))
    if s.startswith('$') and s.endswith('$'):
        body=s[1:-1].strip()
        return {"func":"equation","block":False,"body":{"func":"symbol","text":body}}
    if s.startswith('(') and s.endswith(')'):
        inner=s[1:-1].strip()
        if inner=='': return []
        parts=split_top(inner)
        isdict=all(re.match(r'^[A-Za-z_]\w*\s*:', p) for p in parts)
        if isdict:
            d={}
            for p in parts:
                k,v=p.split(':',1); d[k.strip()]=eval_expr(v,inputs)
            return d
        return [eval_expr(p,inputs) for p in parts if p]
    # safe arithmetic for simple numeric expressions
    if re.fullmatch(r'[0-9+\-*/% ().]+', s):
        try:
            val=eval(s, {"__builtins__":{}}, {})
            if isinstance(val,(int,float)): return val
        except ZeroDivisionError: raise EvalError('cannot divide by zero')
        except Exception: pass
    raise EvalError(f"unknown variable: {s}")

def yaml_dump(v, indent=0):
    sp='  '*indent
    if isinstance(v, dict):
        lines=[]
        for k,val in v.items():
            if isinstance(val,(dict,list)):
                lines.append(f"{sp}{k}:")
                lines.append(yaml_dump(val, indent+1 if isinstance(val,dict) else indent))
            else:
                lines.append(f"{sp}{k}: {yaml_scalar(val)}")
        return '\n'.join(lines)
    if isinstance(v, list):
        lines=[]
        for item in v:
            if isinstance(item,(dict,list)):
                lines.append(f"{sp}-")
                lines.append(yaml_dump(item, indent+1))
            else:
                lines.append(f"{sp}- {yaml_scalar(item)}")
        return '\n'.join(lines)
    return sp + yaml_scalar(v)

def yaml_scalar(v):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    return str(v)

EVAL_OPTIONS={'in':'IN','target':'TARGET','format':'FORMAT','pretty':'flag','root':'DIR','input':'key=value','font-path':'DIR','ignore-system-fonts':'flag','ignore-embedded-fonts':'flag','package-path':'DIR','package-cache-path':'DIR','creation-timestamp':'UNIX_TIMESTAMP','jobs':'JOBS','features':'FEATURES','diagnostic-format':'DIAGNOSTIC_FORMAT'}

def cmd_eval(args):
    opts,pos,perr=parse_options(args, EVAL_OPTIONS)
    if isinstance(perr, tuple) and perr[0]=='unexpected': return clap_error(f"unexpected argument '{perr[1]}' found", "executable eval [OPTIONS] <EXPRESSION>", f"to pass '{perr[1]}' as a value, use '-- {perr[1]}'")
    if perr is not None: return perr
    if opts.get('help'):
        sys.stdout.write(HELP['eval']); return 0
    if len(pos)<1: return clap_error("the following required arguments were not provided:\n  <EXPRESSION>", "executable eval <EXPRESSION>")
    fmt=opts.get('format','json')
    if fmt not in ('json','yaml'):
        return clap_error(f"invalid value '{fmt}' for '--format <FORMAT>'\n  [possible values: json, yaml]")
    target=opts.get('target','paged')
    features=[]
    for f in opts.get('features', []) or []: features += str(f).split(',')
    if os.environ.get('TYPST_FEATURES'): features += os.environ['TYPST_FEATURES'].split(',')
    if target=='html' and 'html' not in features:
        sys.stderr.write(HTML_DISABLED); return 1
    if target not in ('paged','html'):
        return clap_error(f"invalid value '{target}' for '--target <TARGET>'\n  [possible values: paged, html]")
    if 'in' in opts:
        _, e = read_input(opts['in'])
        if e: sys.stderr.write(e); return 1
    inputs={}
    for item in opts.get('input',[]) or []:
        if '=' not in item:
            return clap_error(f"invalid value '{item}' for '--input <key=value>': input must be a key and a value separated by an equal sign")
        k,v=item.split('=',1); inputs[k]=v
    try:
        val=eval_expr(' '.join(pos), inputs)
    except EvalError as e:
        sys.stderr.write('error: '+str(e)+'\n'); return 0
    if fmt=='json':
        sys.stdout.write(json.dumps(val, indent=2 if opts.get('pretty') else None, separators=None if opts.get('pretty') else (',',':'))+'\n')
    else:
        sys.stdout.write(yaml_dump(val)+'\n')
    return 0


def env_info():
    envvars=["TYPST_CERT","TYPST_FEATURES","TYPST_FONT_PATHS","TYPST_IGNORE_SYSTEM_FONTS","TYPST_IGNORE_EMBEDDED_FONTS","TYPST_PACKAGE_CACHE_PATH","TYPST_PACKAGE_PATH","TYPST_ROOT","TYPST_UPDATE_BACKUP_PATH","SOURCE_DATE_EPOCH","XDG_CACHE_HOME","XDG_DATA_HOME","FONTCONFIG_FILE","OPENSSL_CONF","NO_COLOR","NO_PROXY","HTTP_PROXY","HTTPS_PROXY","ALL_PROXY"]
    font_paths=[p for p in os.environ.get('TYPST_FONT_PATHS','').split(os.pathsep) if p]
    feats=os.environ.get('TYPST_FEATURES','')
    htmlf='html' in [x for x in feats.split(',') if x]
    a11y='a11y-extras' in [x for x in feats.split(',') if x]
    for f in [x for x in feats.split(',') if x and x not in ('html','a11y-extras')]:
        sys.stderr.write(f"error: Unknown runtime feature: `{f}`\n")
    home=str(Path.home())
    data=os.environ.get('XDG_DATA_HOME', home+'/.local/share')
