    pkg=os.environ.get('TYPST_PACKAGE_PATH', data+'/typst/packages')
    pcache=os.environ.get('TYPST_PACKAGE_CACHE_PATH', cache+'/typst/packages')
    return {
      'version':VERSION,
      'build': {'commit':FULL_COMMIT, 'platform': {'os':'linux','arch':'x86_64'}, 'settings': {'self-update':False, 'http-server':True}},
      'features': {'html':htmlf, 'a11y-extras':a11y},
      'fonts': {'paths':font_paths, 'system': not bool(os.environ.get('TYPST_IGNORE_SYSTEM_FONTS')), 'embedded': not bool(os.environ.get('TYPST_IGNORE_EMBEDDED_FONTS'))},
      'packages': {'package-path':pkg, 'package-cache-path':pcache},
      'env': {k: os.environ.get(k) for k in envvars}
    }

def cmd_info(args):
    opts,pos,perr=parse_options(args, {'format':'FORMAT','pretty':'flag'})
    if isinstance(perr, tuple) and perr[0]=='unexpected': return clap_error(f"unexpected argument '{perr[1]}' found", "executable info [OPTIONS]")
    if perr is not None: return perr
    if opts.get('help'):
