    fmt=opts.get('format')
    if fmt and fmt not in ('json','yaml'):
        return clap_error(f"invalid value '{fmt}' for '--format <FORMAT>'\n  [possible values: json, yaml]")
    d=env_info()
    if fmt=='json': sys.stdout.write(json.dumps(d, indent=2 if opts.get('pretty') else None, separators=None if opts.get('pretty') else (',',':'))+'\n')
    elif fmt=='yaml': sys.stdout.write(yaml_dump(d)+'\n')
    else:
