        if a=='--color':
            if i+1>=len(argv): raise SystemExit(clap_error("a value is required for '--color <COLOR>' but none was supplied","executable <--color <COLOR>|--cert <CERT>> <COMMAND>"))
            color=argv[i+1]; i+=2; continue
        if a.startswith('--color='): color=a.split('=',1)[1]; i+=1; continue
        if a=='--cert':
            if i+1>=len(argv): raise SystemExit(clap_error("a value is required for '--cert <CERT>' but none was supplied","executable <--color <COLOR>|--cert <CERT>> <COMMAND>"))
            cert=argv[i+1]; i+=2; continue
        if a.startswith('--cert='): cert=a.split('=',1)[1]; i+=1; continue
        return color,cert,argv[i:]
    return color,cert,[]

def validate_global(color, rest):
    if rest and rest[0] in ('help','-h','--help','-V','--version'): return None
