        a=args[i]
        if dd: pos.append(a); i+=1; continue
        if a=='--': dd=True; i+=1; continue
        if a in ('-h','--help'): opts['help']=True; i+=1; continue
        if a.startswith('-') and a!='-':
            name=None; val=None
            if a.startswith('--'):
                if '=' in a: opt,val=a[2:].split('=',1)
                else: opt=a[2:]
                if opt not in specs: return None,None,('unexpected',a)
                kind=specs[opt]; name=opt
                if kind=='flag': val=True
                elif kind=='optional':
                    if val is None:
                        if i+1<len(args) and not args[i+1].startswith('-'): val=args[i+1]; i+=1
                        else: val=True
                else:
                    if val is None:
                        if i+1>=len(args): return None,None,clap_error(f"a value is required for '--{opt} <{kind}>' but none was supplied")
                        val=args[i+1]; i+=1
            else:
                shorts={'-f':'format','-j':'jobs'}
                if a not in shorts or shorts[a] not in specs: return None,None,('unexpected',a)
                name=shorts[a]; kind=specs[name]
                if i+1>=len(args): return None,None,clap_error(f"a value is required for '{a} <{kind}>' but none was supplied")
                val=args[i+1]; i+=1
            if name in repeat: opts.setdefault(name,[]).append(val)
            else: opts[name]=val
