def html_from_typst(src):
    parts=[]
    for para in re.split(r'\n\s*\n',src.strip()):
        if not para: continue
        m=re.match(r'^(=+)\s+(.*)$',para.strip(),flags=re.S)
        level=min(len(m.group(1)),6) if m else 0
        content=m.group(2) if m else para
        content=re.sub(r'#pagebreak\s*\(\s*\)','',content)
        content=html.escape(content)
        content=re.sub(r'\*([^*]+)\*',r'<strong>\1</strong>',content)
        content=re.sub(r'_([^_]+)_',r'<em>\1</em>',content).replace('\n',' ')
        parts.append(f"    <h{level}>{content}</h{level}>" if level else f"    <p>{content}</p>")
    body='\n'.join(parts) or '    <p></p>'
    return f'<!DOCTYPE html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1">\n  </head>\n  <body>\n{body}\n  </body>\n</html>\n'

def pdf_escape(s): return s.replace('\\','\\\\').replace('(','\\(').replace(')','\\)')
def make_pdf(text):
    lines=text.splitlines()[:60] or ['']; content=['BT','/F1 12 Tf','50 780 Td']
    for i,line in enumerate(lines):
        if i: content.append('0 -16 Td')
        content.append(f'({pdf_escape(line[:120])}) Tj')
    content.append('ET'); stream='\n'.join(content).encode('latin-1','replace')
    objs=[b'<< /Type /Catalog /Pages 2 0 R >>',b'<< /Type /Pages /Kids [3 0 R] /Count 1 >>',b'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>',b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',b'<< /Length '+str(len(stream)).encode()+b' >>\nstream\n'+stream+b'\nendstream']
    data=bytearray(b'%PDF-1.7\n%\x80\x80\x80\x80\n'); offs=[0]
    for n,o in enumerate(objs,1): offs.append(len(data)); data+=f'{n} 0 obj\n'.encode()+o+b'\nendobj\n'
    xref=len(data); data+=f'xref\n0 {len(objs)+1}\n0000000000 65535 f \n'.encode()
    for off in offs[1:]: data+=f'{off:010d} 00000 n \n'.encode()
    data+=f'trailer\n<< /Size {len(objs)+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n'.encode()
    return bytes(data)

def make_svg(text):
    lines=[html.escape(x) for x in text.splitlines()[:60]] or ['']
    body='\n'.join(f'<text x="50" y="{70+i*18}" font-family="serif" font-size="14">{line}</text>' for i,line in enumerate(lines))
    return (f'<svg viewBox="0 0 595.275590551 841.88976378" width="595.275590551pt" height="841.88976378pt" xmlns="http://www.w3.org/2000/svg">\n{body}\n</svg>\n').encode()

def make_png():
    raw=b'\x00\xff\xff\xff\xff'
    def chunk(t,d): return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',1,1,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(raw))+chunk(b'IEND',b'')

def split_pages(src): return re.split(r'#pagebreak\s*\(\s*\)',src) or [src]
def apply_template(path,p,total):
    if '{0p}' in path: path=path.replace('{0p}',str(p).zfill(max(1,len(str(total)))))
    return path.replace('{p}',str(p)).replace('{t}',str(total))
def write_bytes(path,data):
    if path=='-': sys.stdout.buffer.write(data)
    else:
        pp=Path(path); pp.parent.mkdir(parents=True,exist_ok=True) if str(pp.parent)!='.' else None; pp.write_bytes(data)

