def active_features(opts):
    fs=[]
    for f in opts.get('features',[]) or []: fs += [x for x in str(f).split(',') if x]
    if os.environ.get('TYPST_FEATURES'): fs += [x for x in os.environ['TYPST_FEATURES'].split(',') if x]
    return fs

def compile_once(opts,pos,is_watch=False):
    cname='watch' if is_watch else 'compile'
    if len(pos)<1: return clap_error('the following required arguments were not provided:\n  <INPUT>',f'executable {cname} <INPUT> [OUTPUT]')
    if len(pos)>2: return clap_error(f"unexpected argument '{pos[2]}' found",f'executable {cname} [OPTIONS] <INPUT> [OUTPUT]',f"to pass it as a value, use '-- {pos[2]}'")
    inp=pos[0]; outp=pos[1] if len(pos)>1 else None
