        sys.stderr.write(f"error: expected pattern\n  ┌─ {loc}:1:4\n  │\n1 │ #let =\n  │     ^\n\nerror: expected expression\n  ┌─ {loc}:1:6\n  │\n1 │ #let =\n  │       ^\n"); return 1
    pages=split_pages(src)
