    elif fmt=='pdf': write_bytes(outp or '-',make_pdf(plain_text(src)))
    elif fmt=='svg':
        if outp=='-': write_bytes('-',make_svg(plain_text(pages[0])))
        else:
            for i,pg in enumerate(pages,1): write_bytes(apply_template(outp,i,len(pages)),make_svg(plain_text(pg)))
    elif fmt=='png':
        if outp=='-': write_bytes('-',make_png())
        else:
            for i,pg in enumerate(pages,1): write_bytes(apply_template(outp,i,len(pages)),make_png())
    if 'deps' in opts:
        depfmt=opts.get('deps-format','json')
        if depfmt not in ('json','zero','make'): return clap_error(f"invalid value '{depfmt}' for '--deps-format <DEPS_FORMAT>'\n  [possible values: json, zero, make]")
        outs=[]
        if outp and outp!='-': outs=[apply_template(outp,i,len(pages)) for i in range(1,len(pages)+1)] if fmt in ('png','svg') and len(pages)>1 else [outp]
        ins=[] if inp=='-' else [inp]
        dep=(json.dumps({'inputs':ins,'outputs':outs},separators=(',',':')).encode() if depfmt=='json' else ((('\0'.join(ins))+'\0' if ins else '').encode() if depfmt=='zero' else ((outs[0] if outs else '')+': '+(' '.join(ins))+'\n').encode()))
        if opts['deps']=='-': sys.stdout.buffer.write(dep)
        else: Path(opts['deps']).write_bytes(dep)
    if 'timings' in opts:
