        if t=='-': sys.stdout.write('{"traceEvents":[]}')
        else: Path(t).write_text('{"traceEvents":[]}')
    return 0

def cmd_compile(args,watch=False):
    opts,pos,perr=parse_options(args,COMPILE_OPTIONS)
    if isinstance(perr,tuple): return clap_error(f"unexpected argument '{perr[1]}' found",f"executable {'watch' if watch else 'compile'} [OPTIONS] <INPUT> [OUTPUT]",f"to pass '{perr[1]}' as a value, use '-- {perr[1]}'")
