class EvalError(Exception): pass

def split_top(s,sep=','):
    res=[]; cur=[]; dep=0; q=None; esc=False
    for ch in s:
        if q:
            cur.append(ch)
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch==q: q=None
        else:
            if ch in ('"',"'"): q=ch; cur.append(ch)
            elif ch in '([{': dep+=1; cur.append(ch)
            elif ch in ')]}': dep-=1; cur.append(ch)
            elif ch==sep and dep==0: res.append(''.join(cur).strip()); cur=[]
            else: cur.append(ch)
    if cur or s.strip()=='': res.append(''.join(cur).strip())
    return res

def eval_expr(s,inputs=None):
    inputs=inputs or {}; s=s.strip()
    if not s: raise EvalError('expected expression')
    if s.startswith('#'): raise EvalError('the character `#` is not valid in code\n = hint: you are already in code mode\n = hint: try removing the `#`')
    if s.count('(')>s.count(')'): raise EvalError('unclosed delimiter')
    if s in ('true','false'): return s=='true'
    if s=='none': return None
    if s=='sys.inputs': return inputs
    if s=='sys.version': return 'version(0, 14, 2)'
    if re.fullmatch(r'"([^"\\]|\\.)*"',s) or re.fullmatch(r"'([^'\\]|\\.)*'",s): return ast.literal_eval(s)
    if re.fullmatch(r'-?\d+(\.\d+)?',s): return float(s) if '.' in s else int(s)
    if s.startswith('str(') and s.endswith(')'): return str(eval_expr(s[4:-1],inputs))
    if s.startswith('range(') and s.endswith(')'):
        vals=[int(eval_expr(x,inputs)) for x in split_top(s[6:-1]) if x]
        return list(range(vals[0])) if len(vals)==1 else (list(range(vals[0],vals[1])) if len(vals)>=2 else [])
    if s.startswith('$') and s.endswith('$'): return {"func":"equation","block":False,"body":{"func":"symbol","text":s[1:-1].strip()}}
    if s.startswith('(') and s.endswith(')'):
        inner=s[1:-1].strip()
        if not inner: return []
        parts=split_top(inner); isdict=all(re.match(r'^[A-Za-z_]\w*\s*:',p) for p in parts)
        if isdict:
            d={}
            for p in parts:
                k,v=p.split(':',1); d[k.strip()]=eval_expr(v,inputs)
            return d
        return [eval_expr(p,inputs) for p in parts if p]
    if re.fullmatch(r'[0-9+\-*/% ().]+',s):
        try:
            val=eval(s,{"__builtins__":{}},{})
            if isinstance(val,(int,float)): return val
        except ZeroDivisionError: raise EvalError('cannot divide by zero')
        except Exception: pass
    raise EvalError(f'unknown variable: {s}')

def yaml_scalar(v):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    return str(v)
def yaml_dump(v,indent=0):
    sp='  '*indent
    if isinstance(v,dict):
        lines=[]
        for k,val in v.items():
            if isinstance(val,(dict,list)): lines.append(f'{sp}{k}:'); lines.append(yaml_dump(val,indent+1 if isinstance(val,dict) else indent))
            else: lines.append(f'{sp}{k}: {yaml_scalar(val)}')
        return '\n'.join(lines)
    if isinstance(v,list):
        lines=[]
        for item in v:
            if isinstance(item,(dict,list)): lines.append(f'{sp}-'); lines.append(yaml_dump(item,indent+1))
            else: lines.append(f'{sp}- {yaml_scalar(item)}')
        return '\n'.join(lines)
    return sp+yaml_scalar(v)

