    return 0

def cmd_fonts(args):
    opts,pos,perr=parse_options(args,{'font-path':'DIR','ignore-system-fonts':'flag','ignore-embedded-fonts':'flag','variants':'flag'})
    if isinstance(perr,tuple): return clap_error(f"unexpected argument '{perr[1]}' found",'executable fonts [OPTIONS]')
    if perr is not None: return perr
    if opts.get('help'): sys.stdout.write(HELP['fonts']); return 0
    sys_on=not(opts.get('ignore-system-fonts') or os.environ.get('TYPST_IGNORE_SYSTEM_FONTS'))
    emb_on=not(opts.get('ignore-embedded-fonts') or os.environ.get('TYPST_IGNORE_EMBEDDED_FONTS'))
    if opts.get('variants') and sys_on and emb_on: sys.stdout.write(FONT_VARIANTS); return 0
    fam=[]
    if sys_on: fam+=FONT_FAMILIES_SYS
    if emb_on: fam+=FONT_FAMILIES_EMB
    for x in FONT_FAMILIES_ALL:
        if x in fam: sys.stdout.write(x+'\n')
    return 0

def cmd_init(args):
    opts,pos,perr=parse_options(args,{'package-path':'DIR','package-cache-path':'DIR'})
    if isinstance(perr,tuple): return clap_error(f"unexpected argument '{perr[1]}' found",'executable init [OPTIONS] <TEMPLATE> [DIR]')
    if perr is not None: return perr
    if opts.get('help'): sys.stdout.write(HELP['init']); return 0
    if not pos: return clap_error('the following required arguments were not provided:\n  <TEMPLATE>','executable init <TEMPLATE> [DIR]')
    if not pos[0].startswith('@'): sys.stderr.write("error: package specification must start with '@'\n"); return 1
    sys.stderr.write('error: failed to fetch package index (https://packages.typst.org/preview/index.json: Connection Failed: Connect error: Network is unreachable (os error 101))\n'); return 1

def cmd_update(args):
    if any(a in ('-h','--help') for a in args): sys.stdout.write(HELP['update']); return 0
    sys.stderr.write('error: self-updating is not enabled for this executable, please update with the package manager or mechanism used for initial installation\n'); return 1

def cmd_query(args):
    if any(a in ('-h','--help') for a in args): sys.stdout.write(HELP['query']); return 0
    opts,pos,perr=parse_options(args,{'field':'FIELD','one':'flag','format':'FORMAT','pretty':'flag','target':'TARGET','root':'DIR','input':'key=value','font-path':'DIR','ignore-system-fonts':'flag','ignore-embedded-fonts':'flag','package-path':'DIR','package-cache-path':'DIR','creation-timestamp':'UNIX_TIMESTAMP','jobs':'JOBS','features':'FEATURES','diagnostic-format':'DIAGNOSTIC_FORMAT'})
    if len(pos)<2: return clap_error('the following required arguments were not provided:\n  <INPUT>\n  <SELECTOR>','executable query <INPUT> <SELECTOR>')
    _,e=read_input(pos[0])
    if e: sys.stderr.write(e); return 1
    if opts.get('one'): sys.stderr.write('error: expected exactly one element, found 0\n'); return 1
    fmt=opts.get('format','json'); sys.stdout.write((yaml_dump([]) if fmt=='yaml' else json.dumps([],indent=2 if opts.get('pretty') else None,separators=None if opts.get('pretty') else (',',':')))+'\n'); return 0

def cmd_completions(args):
    if any(a in ('-h','--help') for a in args): sys.stdout.write(HELP['completions']); return 0
    if not args: return clap_error('the following required arguments were not provided:\n  <SHELL>','executable completions <SHELL>')
    sh=args[0]
    if sh not in ('bash','elvish','fish','powershell','zsh'):
        tip="\n\n  tip: a similar value exists: 'bash'" if sh.startswith('b') else ''
        sys.stderr.write(f"error: invalid value '{sh}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh]{tip}\n\nFor more information, try '--help'.\n"); return 2
    scripts={'bash':'_typst() {\n    COMPREPLY=( $(compgen -W "--color --cert -h --help -V --version compile c watch w init eval fonts completions info help" -- "${COMP_WORDS[COMP_CWORD]}") )\n}\ncomplete -F _typst typst\n','fish':'complete -c typst -f -a "compile c watch w init eval fonts completions info help"\n','zsh':'#compdef typst\n_arguments "*:: :->typst"\n','powershell':"Register-ArgumentCompleter -Native -CommandName 'typst' -ScriptBlock { }\n",'elvish':'set edit:completion:arg-completer[typst] = {|@words| }\n'}
    sys.stdout.write(scripts[sh]); return 0

def normalize(c): return {'c':'compile','w':'watch'}.get(c,c)
def command_help(c): return HELP.get(normalize(c),'')

def main(argv):
    color,cert,rest=parse_global(argv)
    if not rest: sys.stdout.write(WELCOME); return 0
    v=validate_global(color,rest)
    if v is not None: return v
    if rest[0] in ('-V','--version'): sys.stdout.write(f'typst {VERSION} ({SHORT_COMMIT})\n'); return 0
    if rest[0] in ('-h','--help'): sys.stdout.write(MAIN_HELP); return 0
    cmd=rest[0]; args=rest[1:]
    if cmd=='help':
        if not args: sys.stdout.write(MAIN_HELP); return 0
        h=command_help(args[0])
        if h: sys.stdout.write(h); return 0
        return clap_error(f"unrecognized subcommand '{args[0]}'",'executable [OPTIONS] <COMMAND>')
    n=normalize(cmd)
    if n=='compile': return cmd_compile(args,False)
    if n=='watch': return cmd_compile(args,True)
    if n=='eval': return cmd_eval(args)
    if n=='fonts': return cmd_fonts(args)
    if n=='info': return cmd_info(args)
    if n=='init': return cmd_init(args)
    if n=='completions': return cmd_completions(args)
    if n=='query': return cmd_query(args)
    if n=='update': return cmd_update(args)
    if cmd.startswith('-'): return clap_error(f"unexpected argument '{cmd}' found",'executable <--color <COLOR>|--cert <CERT>> <COMMAND>')
    return clap_error(f"unrecognized subcommand '{cmd}'",'executable [OPTIONS] <COMMAND>')

if __name__=='__main__':
    try: raise SystemExit(main(sys.argv[1:]))
    except BrokenPipeError: raise SystemExit(1)
